<template>
  <div class="space-y-6">
    <PageHeader title="出口组" parent="代理" description="将同一节点的多个出站组成调度目标。保存为草稿，配置发布后由 Agent 探测和选择出口。"><template #actions><button @click="openCreate" class="ios-btn-primary">创建出口组</button><button @click="load" class="ios-btn-secondary">刷新</button></template></PageHeader>
    <div class="flex items-center gap-3">
      <span class="text-xs font-medium text-ios-secondary">所属节点</span>
      <select v-model="nodeId" @change="page = 1; load()" class="ios-filter-select">
        <option value="">全部节点</option>
        <option v-for="node in nodes" :key="node.id" :value="node.id">{{ node.name }}</option>
      </select>
    </div>
    <ErrorState v-if="error" :message="error" @retry="load" /><LoadingSkeleton v-else-if="loading && !groups.length" /><EmptyState v-else-if="!groups.length" title="暂无出口组" description="先创建出站，再选择组成员和调度方式。" />
    <DataTable v-else><template #header><th>名称 / 节点</th><th>调度方式</th><th>成员与最近探测</th><th>探测 / 失败策略</th><th>状态</th><th>操作</th></template><template #body><tr v-for="group in groups" :key="group.id">
      <td class="p-4 font-semibold">{{ group.name }}<p class="text-xs font-normal text-gray-500">{{ nodeName(group.nodeId) }}</p></td><td>{{ strategyNames[group.strategy] }}</td>
      <td class="py-3 text-xs"><p v-for="entry in group.members" :key="entry.outbound_id" class="mb-1">{{ outboundName(entry.outbound_id) }} · 顺位 {{ entry.priority }}<span class="block text-gray-500">{{ healthLabel(outbounds.find(item => item.id === entry.outbound_id), group.probeInterval) }}</span></p></td>
      <td class="text-xs max-w-56 break-all">{{ group.probeUrl }}<p>{{ group.probeInterval }} 秒 · {{ failureNames[group.failurePolicy] }}</p></td><td><StatusBadge :status="group.enabled ? 'active' : 'disabled'" /></td>
      <td class="space-x-2"><button @click="openEdit(group)" class="ios-action-btn-primary">编辑</button><button @click="makeRevision(group)" class="ios-action-btn-primary">生成配置版本</button><button @click="target = group; removeConfirm = true" class="ios-action-btn-danger">删除</button></td>
    </tr></template><template #footer><Pagination :total="total" :current-page="page" :page-size="20" @update:page="changePage" /></template></DataTable>
    <p class="text-xs text-gray-500">健康结果来自节点最近上报，过期结果不代表可用。草稿成员尚未发布时可能没有探测结果；轮询按新连接选择；sing-box 节点上的轮询渲染为 urltest，按探测结果选择而非严格轮换。</p>
    <FormDrawer v-model="drawer" :title="editing ? '编辑出口组' : '创建出口组'" :loading="saving" @confirm="save" confirm-text="保存草稿">
      <div class="space-y-4 text-sm"><label class="block">名称<input v-model="form.name" maxlength="120" class="form-input-base mt-2" /></label><label class="block">所属节点<select v-model="form.nodeId" :disabled="!!editing" @change="form.members = []; form.backupOutboundId = ''" class="form-input-base mt-2"><option value="">请选择</option><option v-for="node in nodes.filter(item => item.enabled)" :key="node.id" :value="node.id">{{ node.name }}</option></select></label>
        <label class="block">调度方式<select v-model="form.strategy" class="form-input-base mt-2"><option v-for="(name, value) in strategyNames" :key="value" :value="value">{{ name }}</option></select></label>
        <fieldset><legend class="font-semibold mb-2">成员（最多 16 个）</legend><p v-if="!available.length" class="text-xs text-gray-500">请选择节点，并创建启用且支持 TCP 的出站。</p><div v-for="outbound in available" :key="outbound.id" class="border-b border-gray-100 py-3"><label class="block"><input type="checkbox" :checked="!!member(outbound.id)" @change="toggle(outbound.id)" /> {{ outbound.name }} · {{ outbound.protocol }}</label><div v-if="member(outbound.id)" class="grid grid-cols-2 gap-3 mt-2"><label class="text-xs">顺位（小值优先）<input v-model.number="member(outbound.id)!.priority" type="number" min="0" max="1000" class="form-input-base mt-1" /></label></div></div></fieldset>
        <label class="block">探测 URL<input v-model="form.probeUrl" type="url" class="form-input-base mt-2" /></label><label class="block">探测间隔（秒）<input v-model.number="form.probeInterval" type="number" min="3" max="300" class="form-input-base mt-2" /></label>
        <label class="block">全部成员不可用时<select v-model="form.failurePolicy" class="form-input-base mt-2"><option value="Block">阻断</option><option value="Direct">直连</option><option value="BackupOutbound">备用出站</option><option value="BackupOutboundGroup">备用出口组</option><option value="BackupProxyChain">备用代理链</option></select></label><label v-if="form.failurePolicy.startsWith('Backup')" class="block">备用目标<select v-model="form.backupOutboundId" class="form-input-base mt-2"><option value="">请选择</option><option v-for="backup in backupOptions" :key="backup.id" :value="backup.id">{{ backup.name }}</option></select></label>
        <p v-if="form.failurePolicy === 'Direct'" class="text-xs text-amber-700">全部成员不可用时将从当前节点直连。需要固定出口的网站建议选择阻断或备用出口。</p><label><input v-model="form.enabled" type="checkbox" /> 启用</label><p class="text-xs text-gray-500">出口组用于节点内部调度；用户订阅权限仍由线路组管理。</p>
      </div>
    </FormDrawer>
    <ConfirmDialog v-model="removeConfirm" title="删除出口组草稿" :message="'删除 ' + (target?.name || '') + '？被入站或策略引用的出口组不能删除。运行节点需重新发布才会改变。'" @confirm="remove" />
  </div>
</template>
<script setup lang="ts">
import { ref, reactive, computed, onMounted, onUnmounted } from 'vue';
import { useRouter } from 'vue-router';
import { proxyAPI, choices, strategyNames, healthLabel, type OutboundGroup, type GroupInput, type Outbound, type ProxyChain, failureNames } from '../api';
import { request, type Page } from '../../../app/apiClient'; import { type NodeView } from '../../nodes/api'; import { showToast } from '../../../app/api';
import PageHeader from '../../../components/PageHeader.vue'; import DataTable from '../../../components/DataTable.vue'; import StatusBadge from '../../../components/StatusBadge.vue'; import Pagination from '../../../components/Pagination.vue'; import FormDrawer from '../../../components/FormDrawer.vue'; import ConfirmDialog from '../../../components/ConfirmDialog.vue'; import ErrorState from '../../../components/ErrorState.vue'; import LoadingSkeleton from '../../../components/LoadingSkeleton.vue'; import EmptyState from '../../../components/EmptyState.vue';
const allGroups = ref<OutboundGroup[]>([]); const chains = ref<ProxyChain[]>([]); const router = useRouter(); const groups = ref<OutboundGroup[]>([]); const nodes = ref<NodeView[]>([]); const outbounds = ref<Outbound[]>([]); const nodeId = ref(''); const page = ref(1); const total = ref(0); const loading = ref(false); const error = ref(''); const drawer = ref(false); const saving = ref(false); const editing = ref<OutboundGroup | null>(null); const target = ref<OutboundGroup | null>(null); const removeConfirm = ref(false);
function defaults(): GroupInput { return { name: '', nodeId: nodeId.value, strategy: 'primary', enabled: true, members: [], probeUrl: 'https://www.gstatic.com/generate_204', probeInterval: 30, failurePolicy: 'Block', backupOutboundId: '' }; }
const form = reactive<GroupInput>(defaults()); const backupOptions = computed(() => form.failurePolicy === 'BackupOutboundGroup' ? allGroups.value.filter(item => item.enabled && item.nodeId === form.nodeId && item.id !== editing.value?.id) : form.failurePolicy === 'BackupProxyChain' ? chains.value.filter(item => item.enabled && item.nodeIds[0] === form.nodeId) : available.value); const available = computed(() => outbounds.value.filter(item => item.nodeId === form.nodeId && item.enabled && item.supportTcp && item.protocol !== 'block'));
function nodeName(id: string) { return nodes.value.find(node => node.id === id)?.name || id; } function outboundName(id: string) { return outbounds.value.find(item => item.id === id)?.name || id; }
function member(id: string) { return form.members.find(item => item.outbound_id === id); }
function toggle(id: string) { if (member(id)) form.members = form.members.filter(item => item.outbound_id !== id); else if (form.members.length < 16) form.members.push({ outbound_id: id, priority: form.members.length, weight: 1 }); else showToast('最多选择 16 个成员', 'error'); }
async function load() { if (loading.value) return; loading.value = true; try { const [result, ns, outs, gs, cs] = await Promise.all([proxyAPI.groups(nodeId.value, page.value), choices((p, s) => request<Page<NodeView>>('/nodes?page=' + p + '&pageSize=' + s)), choices((p, s) => proxyAPI.outbounds('', p, s)), choices((p,s) => proxyAPI.groups('',p,s)), choices((p,s) => proxyAPI.chains('',p,s))]); groups.value = result.items; total.value = result.total; nodes.value = ns; outbounds.value = outs; allGroups.value = gs; chains.value = cs; error.value = ''; } catch (e) { error.value = (e as Error).message; } finally { loading.value = false; } }
function changePage(value: number) { page.value = value; load(); } function openCreate() { editing.value = null; Object.assign(form, defaults()); drawer.value = true; }
function openEdit(group: OutboundGroup) { editing.value = group; Object.assign(form, { name: group.name, nodeId: group.nodeId, strategy: group.strategy, enabled: group.enabled, members: group.members.map(item => ({ ...item })), probeUrl: group.probeUrl, probeInterval: group.probeInterval, failurePolicy: group.failurePolicy, backupOutboundId: group.backupOutboundId }); drawer.value = true; }
async function save() { if (saving.value) return; if (!form.name.trim() || !form.nodeId || !form.members.length) { showToast('请填写名称、节点和成员', 'error'); return; } saving.value = true; try { await proxyAPI.saveGroup(editing.value?.id || null, { ...form, members: form.members.map(item => ({ ...item })), backupOutboundId: form.failurePolicy.startsWith('Backup') ? form.backupOutboundId : '' }); drawer.value = false; showToast('出口组草稿已保存，请生成并发布节点配置'); await load(); } catch (e) { showToast((e as Error).message, 'error'); } finally { saving.value = false; } }
async function remove() { if (!target.value) return; try { await proxyAPI.deleteGroup(target.value.id); showToast('出口组草稿已删除'); await load(); } catch (e) { showToast((e as Error).message, 'error'); } }
async function makeRevision(group: OutboundGroup) { try { await proxyAPI.revision(group.nodeId, '更新出口组 ' + group.name); await router.push('/system/revisions'); } catch (e) { showToast((e as Error).message, 'error'); } }
onMounted(() => { load(); window.addEventListener('proxy-node-status', load); }); onUnmounted(() => window.removeEventListener('proxy-node-status', load));
</script>
